import { Controller, Post, Param } from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';

@Controller('videos')
export class VideoController {
  constructor(
    @InjectQueue('video') private readonly videoQueue: Queue,
  ) {}

  @Post(':id/process')
  async processVideo(@Param('id') videoId: string) {
    // Enqueue a transcode job for this video; a separate worker
    // (VideoProcessor) picks it up and does the actual encoding.
    await this.videoQueue.add('transcode', { videoId });

    // Respond right away so the client isn't kept waiting on the
    // (potentially slow) transcoding work.
    return { status: 'done' };
  }
}
